#include <array>
#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include "../Source/F0WholeNoteDetectorV1.h"
#include "F0WholeNoteExtendedEightProbe.cpp"
namespace{
struct Pub{bool has=false,transition=false,primitiveValidated=false;double stable=0;static double cents(double a,double b){return(a>0&&b>0)?std::abs(1200.0*std::log2(a/b)):1e9;}void seed(double hz,bool pv){has=true;stable=hz;primitiveValidated=pv;transition=false;}void apply(const F0WholeNoteDetectorV1::Analysis&a){if(!a.valid){transition=true;primitiveValidated=false;return;}if(a.ambiguousPrimitive){bool same=has&&cents(a.hz,stable)<=100;bool oldPrimitive=primitiveValidated&&has&&cents(.5*a.hz,stable)<=100;if(same||oldPrimitive){transition=false;return;}transition=true;return;}stable=a.hz;has=true;transition=false;primitiveValidated=a.primitiveLowered;}};
template<std::size_t N>void run(const char*name,const std::array<std::uint32_t,N>&seeds){constexpr std::array<double,10>lowNotes{110,123.4708,146.8324,164.8138,196,220,246.9417,293.6648,329.6276,440};constexpr std::array<double,3>snrs{18,9,3};F0WholeNoteDetectorV1 d;d.prepare(48000,55,1600);std::array<float,1536>f{};int cases=0,targetCorrect=0,targetAmbiguous=0,heldOld=0,transitioned=0,publishedTarget=0,publishedWrong=0;for(const auto&p:profiles)for(double low:lowNotes)for(double snr:snrs)for(auto seed:seeds){double target=2*low;auto x=makePrefixStableExtendedVoiceLike(p,target,snr,seed^static_cast<std::uint32_t>(target*97));for(int i=0;i<1536;++i)f[(std::size_t)i]=(float)x[(std::size_t)i];auto a=d.analyse(f.data(),1536);++cases;bool correct=a.valid&&Pub::cents(a.hz,target)<=100;if(correct)++targetCorrect;if(a.ambiguousPrimitive&&correct)++targetAmbiguous;Pub s;s.seed(low,true);s.apply(a);if(s.transition)++transitioned;else if(Pub::cents(s.stable,low)<=100)++heldOld;else if(Pub::cents(s.stable,target)<=100)++publishedTarget;else ++publishedWrong;}std::cout<<"OCTAVE_CHANGE set="<<name<<" cases="<<cases<<" target_correct="<<targetCorrect<<" target_ambiguous="<<targetAmbiguous<<" held_old="<<heldOld<<" transitioned="<<transitioned<<" published_target="<<publishedTarget<<" published_wrong="<<publishedWrong<<'\n';}
}
int main(){constexpr std::array<std::uint32_t,8>A{0x0d95748fu,0x728eb658u,0x718bcd58u,0x82154aeeu,0x7b54a41du,0xc25a59b5u,0x9c30d539u,0x2af26013u},B{0xa4093822u,0x299f31d0u,0x082efa98u,0xec4e6c89u,0x452821e6u,0x38d01377u,0xbe5466cfu,0x34e90c6cu},C{0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u,0xc1059ed8u,0x367cd507u};run("a",A);run("b",B);run("c",C);}
